import{_ as t,o as a,c as n,l as r,t as o,N as s}from"./chunks/framework.CMqbtke2.js";const f=JSON.parse('{"title":"wc | x-cmd man (man1) | print newline, word, and byte counts for each file","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | wc - print newline, word, and byte counts for each file","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"wc | x-cmd man (man1) | print newline, word, and byte counts for each file"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | wc - print newline, word, and byte counts for each file"}]]},"headers":[],"params":{"isMan":true,"man":"wc","category":"man1","desc":"print newline, word, and byte counts for each file"},"relativePath":"man1/wc.md","filePath":"man1/wc.md"}'),i={name:"man1/wc.md"},d={class:"visually-hidden"},l=s('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>wc - print newline, word, and byte counts for each file</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>wc</strong> [<em>OPTION</em>]... [<em>FILE</em>]... <br> <strong>wc</strong> [<em>OPTION</em>]... <em>--files0-from=F</em></p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Print newline, word, and byte counts for each FILE, and a total line if more than one FILE is specified. A word is a non-zero-length sequence of printable characters delimited by white space.</p><p>With no FILE, or when FILE is -, read standard input.</p><p>The options below may be used to select which counts are printed, always in the following order: newline, word, character, byte, maximum line length.</p><dl><dt><strong>-c</strong>, <strong>--bytes</strong></dt><dd>print the byte counts</dd><dt><strong>-m</strong>, <strong>--chars</strong></dt><dd>print the character counts</dd><dt><strong>-l</strong>, <strong>--lines</strong></dt><dd>print the newline counts</dd><dt><strong>--files0-from</strong>=<em>F</em></dt><dd>read input from the files specified by NUL-terminated names in file F; If F is - then read names from standard input</dd><dt><strong>-L</strong>, <strong>--max-line-length</strong></dt><dd>print the maximum display width</dd><dt><strong>-w</strong>, <strong>--words</strong></dt><dd>print the word counts</dd><dt><strong>--total</strong>=<em>WHEN</em></dt><dd>when to print a line with total counts; WHEN can be: auto, always, only, never</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by Paul Rubin and David MacKenzie.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p>Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/wc%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/wc\\</a>&gt; <br> or available locally via: info &#39;(coreutils) wc invocation&#39;</p>',17);function c(e,h,p,m,g,u){return a(),n("div",null,[r("h1",d,o(e.$params.man),1),l])}const b=t(i,[["render",c]]);export{f as __pageData,b as default};
